<?php require __DIR__.'/../config/config.php';require __DIR__.'/../includes/functions.php';$book=['id_buku'=>'','judul'=>'','pengarang'=>'','penerbit'=>'','tahun_terbit'=>'','stok'=>'0'];$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){$book=array_map(fn($x)=>trim($x),array_merge($book,$_POST));$book['id_buku']=strtoupper($book['id_buku']);if(!preg_match('/^B\d{3}$/',$book['id_buku']))$errors[]='ID buku harus berformat Bxxx, contoh B008.';if($book['judul']==='')$errors[]='Judul wajib diisi.';if($book['pengarang']==='')$errors[]='Pengarang wajib diisi.';if($book['tahun_terbit']!==''&&!ctype_digit($book['tahun_terbit']))$errors[]='Tahun terbit harus angka.';if(!ctype_digit($book['stok']))$errors[]='Stok harus angka >= 0.';if(!$errors){try{$s=$pdo->prepare('INSERT INTO buku VALUES(?,?,?,?,?,?)');$s->execute([$book['id_buku'],$book['judul'],$book['pengarang'],$book['penerbit']?:null,$book['tahun_terbit']?:null,$book['stok']]);flash('success','Buku berhasil ditambahkan.');redirect('index.php');}catch(PDOException $e){$errors[]=$e->errorInfo[1]==1062?'ID buku sudah digunakan.':'Gagal menyimpan buku.';}}}$title='Tambah Buku';$edit=false;require __DIR__.'/../includes/header.php';?><h3 class="mb-3">Tambah Buku</h3><?php require '_form.php';require __DIR__.'/../includes/footer.php';?>
